import {seed,sum,money,plan,demand,cost,selectedPlan,approve,validateRecord,checkMidday,outcome,clone} from './model.js';
const KEY='tantsa-demo-v1';
function hydrate(saved){const base=seed();if(!saved||![1,2].includes(saved.version))return base;const products=(saved.products||base.products).map((p,i)=>({...p,unit:p.unit||base.products[i]?.unit||'unit'}));return {...base,...saved,version:2,business:{...base.business,...(saved.business||{})},products};}
let state;try{state=hydrate(JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('saktoserve-demo-v1')));}catch{state=seed();}
const icons=['◫','＋','▦','✓','◷','▤'];
const pages=[['today','Today'],['record','Quick record'],['plan',"Tomorrow’s plan"],['review','Review & approve'],['midday','Midday check'],['end','Day-end review']];
let settings=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>`&#${c.charCodeAt(0)};`);
const product=(p,i)=>`<div class="product"><span class="product-icon p${i%3}">0${i+1}</span><div><b>${esc(p.name)}</b><small>${money(p.price)} / ${esc(p.unit||'unit')}</small></div></div>`;
const btn=(text,action,kind='')=>`<button class="button ${kind}" data-action="${action}">${text}</button>`;
const heading=(eyebrow,title,sub,action='')=>`<header class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</header>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Keep this tab open.');}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3200);}
function go(view){state.view=view;save();render();window.scrollTo({top:0,behavior:'instant'});}
function stat(label,value,note,highlight=false,icon='◦'){return `<div class="stat ${highlight?'highlight':''}"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><strong>${value}</strong><small>${note}</small></div>`;}
function today(){const t=state.today,p=plan(state),remaining=sum(t.prepared)-sum(t.sold)-sum(t.discarded);return `${heading('THURSDAY, SEPTEMBER 24 · DEMO DAY',`Good afternoon, ${esc(state.business.owner)}.`,'A little clarity for today. A better start for tomorrow.',btn('＋ &nbsp; Quick record','nav:record','light'))}<div class="stats">${stat('Prepared today',sum(t.prepared),`${state.products.length} configured products`,false,'▦')}${stat('Units sold',sum(t.sold),`${Math.round(sum(t.sold)/sum(t.prepared)*100)}% of today’s production`,false,'↗')}${stat('Still on the shelf',remaining,'units available for walk-ins',true,'◫')}${stat('Recorded sales',money(sum(state.products.map((p,i)=>p.price*t.sold[i]))),'before ingredient & operating costs',false,'₱')}</div><div class="cols"><div class="stack"><section class="card"><div class="card-head"><div><h2>On the counter</h2><p>Today’s production and sales</p></div><span class="pill">${esc(state.business.type)} open</span></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>PREPARED</th><th>SOLD</th><th>LEFT</th></tr></thead><tbody>${state.products.map((pr,i)=>`<tr><td>${product(pr,i)}</td><td>${t.prepared[i]}</td><td>${t.sold[i]}</td><td><span class="remaining">${t.prepared[i]-t.sold[i]-t.discarded[i]} units</span></td></tr>`).join('')}</tbody></table></div><div class="card-foot"><span>Includes ${sum(t.preorderSold)} collected preorder units</span><button class="link" data-action="nav:record">Update counts ↗</button></div></section><section class="card"><div class="card-head"><div><h2>A little history helps</h2><p>Sample Friday walk-in sales · preorders excluded</p></div><span class="tag">${state.history.filter(h=>h.day==='Friday').length} comparable days</span></div><div class="chart">${state.history.filter(h=>h.day==='Friday').map(h=>`<div class="chart-row"><span>${h.date}</span><div class="bar-track"><div class="bar" style="width:${sum(h.walkin)/1.2}%"></div></div><b>${sum(h.walkin)}</b></div>`).join('')}<div class="chart-row target"><span>Estimate</span><div class="bar-track"><div class="bar" style="width:${Math.min(100,sum(p.walkin)/1.2)}%"></div></div><b>${sum(p.walkin)}</b></div><div class="legend"><span><i class="dot"></i>Recorded walk-ins</span><span><i class="dot dark"></i>Tomorrow’s estimate</span></div></div></section></div><div class="stack"><section class="card plan-card"><div class="eyebrow">A LOOK AT TOMORROW &nbsp; ↗</div><h2>Prepare with a plan.</h2><div class="plan-total"><strong class="big">${sum(p.total)}</strong><span>units, at most</span></div><div class="plan-formula">${sum(p.walkin)} expected walk-ins + ${sum(state.orders)} confirmed orders</div><p>Your usual production is 120 units in this sample. Start smaller, then let the day guide the next batch.</p><div class="split"><div><strong>${sum(p.initial)}</strong><small>Prepare initially</small></div><div><strong>${sum(p.conditional)}</strong><small>Conditional at midday</small></div></div>${btn('Plan tomorrow <span>→</span>','nav:plan','lime')}<p class="plan-note">Your call, always. Review before approving.</p></section><div class="banner"><div><div class="eyebrow">MADE FOR YOUR EVERYDAY</div><h3>Every batch starts with a little care.</h3><p>Ingredients, cash, and customers.<br>One practical decision.</p></div><img src="pandesal.jpg" alt="Sample prepared product" /></div></div></div>`;}
function initials(name){return String(name||'SS').split(/\s+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();}
function render(){document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand" data-action="nav:today" role="button" tabindex="0"><img src="logo.png" alt="TANTSA Logo" class="brand-logo"><div>TANT<span>SA</span></div></div><div class="brand-caption">Guess less. Make right. Earn more.</div><div class="nav-label">YOUR DAILY WORKFLOW</div><nav class="nav" aria-label="Daily workflow">${pages.map(([id,title],i)=>`<button data-action="nav:${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}><span class="nav-icon">${icons[i]}</span>${title}<span class="nav-num">${i+1}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="nav"><button data-action="settings"><span class="nav-icon">⚙</span>Business & products</button><button data-action="reset"><span class="nav-icon">↺</span>Reset demo</button></div><div class="business-id"><div class="avatar">${initials(state.business.name)}</div><div><strong>${esc(state.business.name)}</strong><small>Fictional ${esc(state.business.type.toLowerCase())} · sample data</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">${esc(state.business.name)} &nbsp; / &nbsp; <b>${pages.find(p=>p[0]===state.view)?.[1]||'Today'}</b></div><div class="brand mobile-brand" data-action="nav:today" role="button" tabindex="0"><img src="logo.png" alt="TANTSA Logo" class="brand-logo"><div>TANT<span>SA</span></div></div><div class="top-right"><span>Saved on this device</span><span class="pill sample">ILLUSTRATIVE DEMO</span><button class="topbar-action-btn mobile-only-btn" data-action="settings" title="Settings" aria-label="Settings">⚙</button><button class="topbar-action-btn mobile-only-btn" data-action="reset" title="Reset demo" aria-label="Reset demo">↺</button><div class="avatar">${initials(state.business.owner)}</div></div></header><main class="main"><div class="content-enter">${screen()}</div><footer class="footer"><span>Sample data, real calculations. No savings claim.</span><span><button class="link" data-action="settings">Settings</button> · <button class="link" data-action="reset">Reset demo</button></span></footer></main></div></div>${settings?settingsPanel():''}`;}
function screen(){return ({today,record,plan:planning,review,midday,end}[state.view]||today)();}


render();
function planning(){const p=plan(state),shortfall=sum(p.target)-sum(p.total);return `${heading('FRIDAY, SEPTEMBER 25 · TOMORROW','Kasya sa puhunan.','Start with what you have. Make a plan your budget can carry.')}<div class="steps"><span>1 &nbsp; Budget & orders</span>→ &nbsp; 2 &nbsp; Review & approve</div><div class="cols"><div class="stack"><section class="card form-card"><div style="display:flex;justify-content:space-between;align-items:center"><h2>Your purchasing budget</h2><span class="pill">Kasya sa Puhunan</span></div><p class="small" style="margin-top:8px">Cash available for extra ingredients. Stock on hand counts, too.</p><label class="budget-value">₱ <input id="budget" aria-label="Purchasing budget in pesos" type="number" min="0" max="10000" step="1" value="${state.budget/100}" data-field="budget"></label><input class="budget-slider" aria-label="Adjust purchasing budget" type="range" min="0" max="600" step="1" value="${Math.min(600,state.budget/100)}" data-field="budget"><div class="range-labels"><span>₱0 · use existing stock</span><span>₱600</span></div><div class="budget-buttons">${[0,150,300,500].map(n=>`<button class="${state.budget===n*100?'active':''}" data-action="budget:${n}">${money(n*100)}</button>`).join('')}</div><div class="notice ${p.errors.length?'error':shortfall?'warn':''}"><strong>${p.errors.length?'Confirmed orders need attention':shortfall?`${shortfall} walk-in units held back`:'Your full plan fits.'}</strong>${p.errors.length?p.errors.join(' '):shortfall?`At ${money(state.budget)}, plan for ${sum(p.total)} of the ${sum(p.target)} target units. All ${sum(state.orders)} confirmed orders remain reserved. We add initial batches first, then conditional batches in menu order.`:`${money(p.cash)} covers all needed purchase packs. ${money(state.budget-p.cash)} stays outside the purchasing plan.`}</div><hr class="divider"><h3>Confirmed preorders</h3><p class="small" style="margin-top:5px">Reserved in the initial preparation. Separate from walk-in demand.</p><div class="input-grid">${state.products.map((pr,i)=>`<label class="field">${pr.name}<input type="number" min="0" max="600" step="1" value="${state.orders[i]}" data-field="order" data-index="${i}" aria-label="${pr.name} confirmed preorders"></label>`).join('')}</div><p class="small">${sum(state.orders)} units committed · never silently reduced</p></section><section class="card"><div class="card-head"><div><h2>Why this estimate?</h2><p>${p.source} · sample data only</p></div><span class="tag">Simple average</span></div><div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>WALK-INS</th><th>PREORDERS</th><th>TARGET</th></tr></thead><tbody>${state.products.map((pr,i)=>`<tr><td>${product(pr,i)}</td><td>${p.walkin[i]}</td><td>+ ${state.orders[i]}</td><td><b>${p.target[i]}</b></td></tr>`).join('')}</tbody></table></div><div class="accordion"><details><summary>See the sample records & calculation</summary><p>Average comparable walk-in sales per product, add tomorrow’s confirmed orders once, then round up to whole recipe batches. Initial preparation: orders + half of estimated walk-ins, rounded up. Remaining batches wait for midday.</p><table><thead><tr><th>Sample date</th>${state.products.map(pr=>`<th>${pr.name}</th>`).join('')}<th>Orders excluded</th></tr></thead><tbody>${state.history.filter(h=>h.day==='Friday').map(h=>`<tr><td>${h.date}</td>${h.walkin.map(n=>`<td>${n}</td>`).join('')}<td>${sum(h.preorders)}</td></tr>`).join('')}</tbody></table><p>${p.early?'An early sellout was recorded. Observed sales may understate true demand; no extra demand is invented.':'No early sellouts in the original three sample Fridays.'} ${p.limited?'Limited history: treat this as an uncertain baseline.':''}</p></details></div></section></div><div class="stack"><section class="card plan-card"><div class="eyebrow">${p.errors.length?'REQUIRED MINIMUM · NOT FEASIBLE':'YOUR FEASIBLE PLAN'}</div><h2>${p.errors.length?'Resolve before preparing.':'A smaller start. Room to respond.'}</h2><div class="plan-total"><strong class="big">${sum(p.total)}</strong><span>units, at most</span></div><div class="split"><div><strong>${sum(p.initial)}</strong><small>Initially · ${sum(state.orders)} reserved</small></div><div><strong>${sum(p.conditional)}</strong><small>Conditional at midday</small></div></div><p>${p.errors.length?'This required minimum is not feasible yet. Increase resources or resolve orders with the customer.':'Whole batches. Preorders first. You review the final quantities.'}</p>${btn('Review this plan →','nav:review','lime')}</section>${costCard(p)}<div class="card form-card"><h3>Your kitchen’s limit</h3><div class="math"><span>Preparation time</span><b>${p.minutes} / ${state.capacity} min</b><span>Recipe batches</span><b>${sum(p.total.map((n,i)=>n/state.products[i].batch))}</b></div><p class="small">One sequential preparation station. Ingredients for conditional batches are included in purchases.</p></div></div></div>`;}
function costCard(p){return `<section class="card"><div class="card-head"><h2>Two different costs</h2></div><div style="padding:0 24px 15px"><div class="math"><span>Cash needed for purchases</span><b>${money(p.cash)}</b><span>Ingredients consumed if all prepared</span><b>${money(p.consumed)}</b></div><p class="small">Purchases use whole packs. Ingredient cost includes stock you already own and only the quantities used.</p></div><div class="accordion"><details><summary>Ingredient stock & shopping list</summary><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Have</th><th>Need</th><th>Buy</th><th>Cash</th></tr></thead><tbody>${p.lines.map(g=>`<tr><td>${g.name} (${g.unit})</td><td>${g.stock}</td><td>${g.used}</td><td>${g.packs} × ${g.pack}</td><td>${money(g.cash)}</td></tr>`).join('')}</tbody></table></div></details></div></section>`;}
function review(){const p=selectedPlan(state);return `${heading('THE OWNER HAS THE FINAL SAY','A plan you can stand behind.','Change quantities in whole batches. Costs and warnings update with every change.',btn('← Back to budget','nav:plan','light'))}<div class="steps">1 &nbsp; Budget & orders &nbsp; → <span>2 &nbsp; Review & approve</span></div>${state.approval?`<div class="notice"><strong>Plan approved and saved on this device.</strong>${sum(state.approval.initial)} units in the initial preparation. ${sum(state.approval.orders)} reserved for preorders. ${sum(state.approval.conditional)} conditional.</div>`:''}<div class="cols"><div class="stack"><section class="card"><div class="card-head"><div><h2>Tomorrow’s production sheet</h2><p>Initial preparation includes reserved units; total includes conditional batches.</p></div><button class="link" data-action="restore-plan">Use suggestion</button></div><div class="table-wrap"><table class="record-table"><thead><tr><th>PRODUCT</th><th>RESERVED</th><th>INITIAL</th><th>MAX. TOTAL</th><th>CONDITIONAL</th></tr></thead><tbody>${state.products.map((pr,i)=>`<tr><td>${product(pr,i)}<small class="muted">${pr.batch} / batch</small></td><td>${state.orders[i]}</td><td><input aria-label="${pr.name} initial quantity" type="number" min="0" max="1200" step="${pr.batch}" value="${p.initial[i]}" data-field="initial" data-index="${i}"></td><td><input aria-label="${pr.name} maximum total" type="number" min="0" max="1200" step="${pr.batch}" value="${p.total[i]}" data-field="total" data-index="${i}"></td><td>${p.conditional[i]}</td></tr>`).join('')}</tbody></table></div><div class="summary-strip"><p>INITIAL PREP<strong>${sum(p.initial)} units</strong></p><p>RESERVED WITHIN INITIAL PREP<strong>${sum(state.orders)} units</strong></p><p>WAIT FOR MIDDAY<strong>${sum(p.conditional)} units</strong></p></div></section>${p.errors.length?`<div class="notice error"><strong>This plan cannot be approved yet.</strong>${p.errors.map(e=>`<div>${e}</div>`).join('')}</div>`:`<div class="notice"><strong>Ready for your approval.</strong>All ${sum(state.orders)} confirmed units are protected, purchases fit ${money(state.budget)}, and ${p.minutes} minutes fit your kitchen’s capacity.</div>`}<div class="card form-card"><h3>The reasoning, in plain language</h3><p class="small" style="margin-top:12px">${sum(p.walkin)} expected walk-ins + ${sum(state.orders)} committed units gives a target of ${sum(p.target)} units after batch rounding. ${state.draft?'You adjusted the suggested quantities.':'The suggestion starts with half of walk-in demand plus all preorders, rounded to batches.'} The full ingredient purchase covers every approved batch, but the conditional preparation waits for fresh sales counts.</p><p class="small" style="margin-top:12px">Approving the illustrative plan starts tomorrow’s demo. It does not place a purchase order.</p></div></div><div class="stack">${costCard(p)}<section class="card form-card"><h3>Your decision</h3><div class="math"><span>Planned preparation</span><b>${p.minutes} / ${state.capacity} min</b><span>Purchasing budget</span><b>${money(state.budget)}</b></div><button class="button" style="width:100%" data-action="approve" ${p.errors.length?'disabled':''}>${state.approval?'Continue to midday →':'Approve plan & start tomorrow →'}</button><p class="small" style="margin-top:13px">Saved locally. Changing the plan or its resources requires fresh approval.</p></section></div></div>`;}
function record(){const r=state.today;return `${heading('A SIMPLE RECORD GOES A LONG WAY','How did today’s production go?','Count all sold units, then separate the preorders. Unsold and discarded stay distinct.')}<form id="record-form"><section class="card"><div class="card-head"><div><h2>Thursday’s quick record</h2><p>Illustrative opening record · ${r.date}</p></div><span class="pill">Whole units</span></div>${recordTable(r,false)}<div style="padding:20px 24px"><label class="checkbox"><input type="checkbox" name="comparable" ${r.comparable?'checked':''}>Use today as a comparable day for tomorrow’s estimate</label><p class="small" style="margin-top:8px">Only select this if you expect similar customers tomorrow. Otherwise, the three sample Fridays remain the comparison.</p></div></section><div id="form-errors" role="alert"></div><div class="action-row"><p>Walk-in history = all units sold − collected preorders. An early sellout flags uncertain demand.</p><button class="button" type="submit">Save record & plan tomorrow →</button></div></form>`;}
function recordTable(r,end){const products=end&&state.approval?state.approval.products:state.products;return `<div class="table-wrap"><table class="record-table"><thead><tr><th>PRODUCT</th><th>PREPARED</th><th>ALL SOLD</th><th>OF SOLD,<br>PREORDERS</th><th>DISCARDED</th><th>EARLY SELLOUT</th></tr></thead><tbody>${products.map((pr,i)=>`<tr><td>${product(pr,i)}</td>${['prepared','sold','preorderSold','discarded'].map(f=>`<td><input name="${f}-${i}" aria-label="${pr.name} ${f}" type="number" min="0" max="1200" step="${f==='prepared'?pr.batch:1}" value="${r[f][i]}" required></td>`).join('')}<td><label class="checkbox"><input aria-label="${pr.name} early sellout" name="early-${i}" type="checkbox" ${r.early?.[i]?'checked':''}>Yes</label></td></tr>`).join('')}</tbody></table></div>`;}
function midday(){const a=state.approval;if(!a)return gated('Midday comes after a plan.','Approve tomorrow’s plan to start the next day’s midday check.');const m=state.midday||middayDefault(a);const result=checkMidday(a,state.midday);const done=!!state.midday?.decision;return `${heading('FRIDAY, SEPTEMBER 25 · 12:00 PM CHECK','Let the day guide the next batch.','The initial preparation is on the counter. Check walk-in sales before preparing more.')}<div class="stats">${stat('Initial prep',sum(a.initial),'units prepared')}${stat('Reserved preorders',sum(a.orders),'kept separate from walk-in stock',true)}${stat('Available for walk-ins',sum(a.initial)-sum(a.orders),'initial preparation minus reserved units')}${stat('Conditional',sum(a.conditional),'units awaiting your decision')}</div><div class="cols"><div class="stack"><form id="midday-form" class="card"><div class="card-head"><div><h2>What’s on the counter now?</h2><p>Unreserved units only · no midday disposal in this scenario</p></div></div><div class="table-wrap"><table class="record-table"><thead><tr><th>PRODUCT</th><th>WALK-IN SOLD</th><th>REMAINING</th></tr></thead><tbody>${a.products.map((pr,i)=>`<tr><td>${product(pr,i)}<small class="muted">${a.initial[i]-a.orders[i]} available originally</small></td><td><input type="number" name="sold-${i}" min="0" max="1200" step="1" required value="${m.sold[i]}" aria-label="${pr.name} midday walk-in sold" ${done?'disabled':''}></td><td><input type="number" name="remaining-${i}" min="0" max="1200" step="1" required value="${m.remaining[i]}" aria-label="${pr.name} midday remaining" ${done?'disabled':''}></td></tr>`).join('')}</tbody></table></div><div style="padding:20px 24px"><div id="form-errors" role="alert"></div>${done?'<div class="notice">Midday decision recorded. Continue to closing to enter the actual outcome.</div>':`<button class="button" type="submit">Update counts & check batches →</button><button class="link" type="button" data-action="slow">Load slower sales example</button>`}</div></form><section class="card form-card"><h3>A small rule, explained</h3><p class="small" style="margin-top:10px">Assume equal morning and afternoon selling windows: afternoon walk-in demand equals this morning’s sales. Recommend one conditional batch per product only when that estimate exceeds remaining stock. Reserved orders stay untouched.</p><p class="small" style="margin-top:10px">Counts expire after 60 minutes. This is a fixed noon demonstration, not a live forecast. Ingredients and capacity were checked for the approved maximum.</p></section></div><div class="stack"><section class="card form-card"><div class="eyebrow">THE NEXT-BATCH DECISION</div><div class="status-title">${done?(m.decision==='delay'?'Additional preparation delayed.':'Additional batches recorded.'):result.status==='stale'?'Fresh counts first.':result.status==='prepare'?'Prepare another batch.':result.status==='blocked'?'Check your counts.':'No rush. Delay preparation.'}</div><div class="notice ${['stale','blocked'].includes(result.status)?'warn':''}">${done?'Your decision is saved. Closing results will reflect what was actually prepared.':result.message}</div>${state.midday&&!done&&['prepare','delay'].includes(result.status)?`<div class="next-batch"><strong>${sum(result.batches)}</strong><span>units recommended now<br>of ${sum(a.conditional)} conditional</span></div>${result.batches.map((n,i)=>n?`<p class="small">${a.products[i].name}: ${n} units</p>`:'').join('')}<button class="button" style="width:100%;margin-top:20px" data-action="midday-decision:${result.status}">${result.status==='prepare'?'Record these batches prepared':'Keep the additional batches on hold'}</button>`:''}${done?btn('Go to day-end review →','nav:end'):''}<p class="small" style="margin-top:16px">${state.midday?`Last update: ${new Date(state.midday.at).toLocaleTimeString('en-PH',{hour:'2-digit',minute:'2-digit'})} · this device`:'No saved midday update yet.'}</p></section></div></div>`;}
function middayDefault(a){const sold=a.initial.map((n,i)=>Math.floor((n-a.orders[i])*(i===2?1/3:1/2)));return {sold,remaining:sold.map((n,i)=>a.initial[i]-a.orders[i]-n),at:Date.now()};}
function gated(title,text){return `${heading('ONE CONNECTED DAILY WORKFLOW',title,text)}<section class="card empty"><h2>Start with tomorrow’s production sheet.</h2><p>Confirm quantities and ingredient purchases before the next day begins.</p>${btn('Review the plan →','nav:review')}</section>`;}
function end(){if(!state.approval)return gated('Close the loop.','Approve a plan before recording its actual results.');const a=state.approval;const prepared=a.initial.map((n,i)=>n+(state.midday?.prepared?.[i]||0));const r=state.outcome||{prepared,sold:prepared.map((n,i)=>Math.min(n,(state.midday?.sold[i]||0)+a.orders[i])),preorderSold:[...a.orders],discarded:a.products.map(()=>0),early:a.products.map(()=>false)};const o=outcome(state,r);return `${heading('FRIDAY, SEPTEMBER 25 · CLOSING','What actually happened?','Record the outcome. Keep sales, unsold units, and disposal separate.')}<div class="notice ${state.outcome?'':'warn'}"><strong>${state.outcome?'Recorded outcome · saved locally':'Closing draft · not yet recorded'}</strong>${state.outcome?'These are entered results from an illustrative scenario, not proof of savings.':'Prepared counts come from your preparation decisions. Sold counts start with recorded midday sales plus reserved orders; confirm actual collections and closing counts before saving.'}</div><form id="end-form"><section class="card"><div class="card-head"><h2>The closing count</h2><span class="tag">All sales at listed price</span></div>${recordTable(r,true)}</section><div id="form-errors" role="alert"></div><div class="action-row"><p>Unsold = prepared − sold − discarded. Estimated contribution excludes labor, utilities, rent, and other operating costs.</p><button class="button" type="submit">Save actual outcome ✓</button></div></form>${state.outcome?`<div class="stats" style="margin-top:26px">${stat('Recorded revenue',money(o.revenue),`${sum(r.sold)} units sold`)}${stat('Unsold, not discarded',o.unsold,'units remaining at close')}${stat('Discarded',o.discarded,'units recorded as disposal')}${stat('Est. contribution',money(o.contribution),'sales less ingredients consumed',true)}</div><section class="card form-card"><h3>What these numbers mean</h3><div class="math"><span>Ingredient cost of actual production</span><b>${money(o.consumed)}</b><span>Approved maximum purchase cash</span><b>${money(a.cost.cash)}</b><span>Confirmed preorder units not collected</span><b>${sum(a.orders)-sum(r.preorderSold)}</b></div><p class="small">Unused conditional ingredients remain inventory, not consumed cost. Purchase cash is the approved plan, not a claim that purchases were completed. This prototype does not recommend resale or carryover.</p></section>`:''}`;}
function settingsPanel(){return `<div class="settings-overlay"><section class="settings" role="dialog" aria-modal="true" aria-labelledby="settings-title" tabindex="-1"><button class="close" data-action="close-settings" aria-label="Close settings">×</button><h2 id="settings-title">Business & product setup</h2><p class="small">The bakery is only the illustrative demo. Change these fields to represent another prepared-food business.</p><form id="settings-form"><div class="card form-card"><h3>Business profile</h3><div class="input-grid"><label class="field">Business name<input name="business-name" type="text" maxlength="60" required value="${esc(state.business.name)}"></label><label class="field">Business type<input name="business-type" type="text" maxlength="40" required value="${esc(state.business.type)}"></label><label class="field">Owner / display name<input name="business-owner" type="text" maxlength="40" required value="${esc(state.business.owner)}"></label></div><p class="small">Examples: bakery, carinderia, café, food stall, kiosk. The planning rules stay the same.</p></div><div class="card"><div class="card-head"><h3>Ingredients & purchase packs</h3></div><div class="table-wrap"><table><thead><tr><th>INGREDIENT</th><th>ON HAND</th><th>PACK SIZE</th><th>₱ / PACK</th></tr></thead><tbody>${state.ingredients.map((g,i)=>`<tr><td>${esc(g.name)} (${esc(g.unit)})</td><td><input aria-label="${esc(g.name)} stock" name="stock-${i}" type="number" min="0" max="100000" step="1" required value="${g.stock}"></td><td><input aria-label="${esc(g.name)} pack size" name="pack-${i}" type="number" min="1" max="100000" step="1" required value="${g.pack}"></td><td><input aria-label="${esc(g.name)} pack cost in pesos" name="cost-${i}" type="number" min="0.01" max="10000" step="0.01" required value="${g.cost/100}"></td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-head"><div><h3>Products & recipes</h3><p>Three sample product slots for the pitch; each slot is configurable.</p></div></div>${state.products.map((p,i)=>`<details><summary><b>${esc(p.name)}</b> <span class="muted">· ${p.batch} per batch</span></summary><div class="input-grid"><label class="field">Product name<input name="name-${i}" type="text" maxlength="40" required value="${esc(p.name)}"></label><label class="field">Unit label<input name="unit-${i}" type="text" maxlength="20" required value="${esc(p.unit||'unit')}"></label><label class="field">Selling price (₱)<input name="price-${i}" type="number" min="0.01" max="10000" step="0.01" required value="${p.price/100}"></label><label class="field">Units per batch<input name="batch-${i}" type="number" min="1" max="120" step="1" required value="${p.batch}"></label><label class="field">Minutes per batch<input name="minutes-${i}" type="number" min="1" max="240" step="1" required value="${p.minutes}"></label></div><p class="small">Recipe quantities for one batch</p>${state.ingredients.map((g,j)=>`<label class="recipe-row">${esc(g.name)} (${esc(g.unit)})<input name="recipe-${i}-${j}" type="number" min="0" max="10000" step="1" required value="${p.recipe[j]}"></label>`).join('')}</details>`).join('')}</div><div class="card form-card"><label class="field">Daily preparation capacity (minutes)<input name="capacity" type="number" min="0" max="1440" step="1" required value="${state.capacity}"></label><hr class="divider"><label class="checkbox"><input type="checkbox" name="useHistory" ${state.useHistory?'checked':''}>Use comparable sample sales history</label><p class="small" style="margin-top:10px">Without history, use these owner-entered walk-in baselines:</p><div class="input-grid">${state.products.map((p,i)=>`<label class="field">${esc(p.name)}<input name="fallback-${i}" type="number" min="0" max="600" step="1" required value="${state.fallback[i]||0}"></label>`).join('')}</div></div><div id="settings-errors" role="alert"></div><div class="notice warn">Saving changes clears the current plan approval and tomorrow’s results so all constraints are checked again.</div><button type="submit" class="button" style="width:100%">Save business settings</button></form></section></div>`;}
function invalidate(){state.approval=null;state.midday=null;state.outcome=null;}
function setBudget(n){if(!Number.isFinite(n)||n<0||n>10000){toast('Enter a purchasing budget from ₱0 to ₱10,000.');return;}state.budget=Math.round(n*100);state.draft=null;invalidate();save();render();}
function errors(list,id='form-errors'){document.getElementById(id).innerHTML=list.length?`<div class="notice error">${list.map(t=>`<div>${t}</div>`).join('')}</div>`:'';}
function readRecord(f){const indexes=state.products.map((_,i)=>i);return Object.fromEntries(['prepared','sold','preorderSold','discarded','early'].map(key=>[key,indexes.map(i=>key==='early'?f.has(`${key}-${i}`):Number(f.get(`${key}-${i}`)))]));}
function bindActions(e){const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action.startsWith('nav:'))return go(action.split(':')[1]);if(action.startsWith('budget:'))return setBudget(Number(action.split(':')[1]));if(action==='settings'){settings=true;render();document.querySelector('.settings').focus();}if(action==='close-settings'){settings=false;render();}if(action==='reset'){state=seed();settings=false;save();render();window.scrollTo(0,0);toast('Demo reset. Ready for the 90-second story.');}if(action==='restore-plan'){state.draft=null;invalidate();save();render();toast('Suggested quantities restored.');}if(action==='approve'){if(!state.approval){try{state.approval=approve(state);state.midday=null;state.outcome=null;}catch(error){toast(error.message);return;}}go('midday');toast('Plan approved. Tomorrow’s initial preparation is ready.');}if(action==='slow'){state.midday=null;render();toast('Slower sales loaded. Save the update to reassess.');}if(action.startsWith('midday-decision:')){const r=checkMidday(state.approval,state.midday);if(!['prepare','delay'].includes(r.status)){toast('Refresh your midday counts before deciding.');render();return;}state.midday.decision=r.status;state.midday.prepared=r.status==='prepare'?r.batches:state.approval.products.map(()=>0);save();render();toast(r.status==='delay'?'Additional batches held back.':'Additional preparation recorded.');}}
function bindInputs(e){const el=e.target;const f=el.dataset.field;if(!f)return;const n=Number(el.value),i=Number(el.dataset.index);if(f==='budget')return setBudget(n);if(!Number.isFinite(n)||n<0||n>1200){toast('Enter a quantity from 0 to 1,200.');return;}if(f==='order'){if(!Number.isSafeInteger(n)){toast('Preorders must be whole units.');render();return;}state.orders[i]=n;state.draft=null;}else{const p=selectedPlan(state);state.draft={total:[...p.total],initial:[...p.initial]};state.draft[f][i]=n;}invalidate();save();render();}
function bindForms(e){e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='record-form'){const r=readRecord(f);const errs=validateRecord(r,state.products,{preorders:true});if(errs.length)return errors(errs);const comparable=f.has('comparable');state.today={...state.today,...r,comparable};state.history=state.history.filter(h=>h.id!=='recorded-today');state.history.push({id:'recorded-today',date:'Sep 24*',day:comparable?'Friday':'Thursday',walkin:r.sold.map((n,i)=>n-r.preorderSold[i]),preorders:r.preorderSold,early:r.early.some(Boolean)});state.draft=null;invalidate();go('plan');toast('Record saved. Preorders excluded from walk-in history.');}if(form.id==='midday-form'){const indexes=state.approval.products.map((_,i)=>i);const m={at:Date.now(),sold:indexes.map(i=>Number(f.get(`sold-${i}`))),remaining:indexes.map(i=>Number(f.get(`remaining-${i}`)))};const result=checkMidday(state.approval,m);if(result.status==='blocked')return errors([result.message]);state.midday=m;state.outcome=null;save();render();toast('Fresh counts saved. Recommendation updated.');}if(form.id==='end-form'){const r=readRecord(f),o=outcome(state,r);if(o.errors.length)return errors(o.errors);const prepared=state.approval.initial.map((n,i)=>n+(state.midday?.prepared?.[i]||0));if(r.prepared.some((n,i)=>n<prepared[i]))return errors(['Prepared counts cannot be lower than batches already recorded.']);if(state.midday&&r.sold.some((n,i)=>n-r.preorderSold[i]<state.midday.sold[i]))return errors(['Closing walk-in sales cannot be lower than recorded midday walk-in sales.']);state.outcome=r;state.history=state.history.filter(h=>h.id!=='recorded-end');state.history.push({id:'recorded-end',date:'Sep 25*',day:'Friday',walkin:r.sold.map((n,i)=>n-r.preorderSold[i]),preorders:r.preorderSold,early:r.early.some(Boolean)});save();render();toast('Actual outcome saved to local history.');}if(form.id==='settings-form'){const next=clone(state);next.business={name:String(f.get('business-name')||'').trim()||state.business.name,type:String(f.get('business-type')||'').trim()||state.business.type,owner:String(f.get('business-owner')||'').trim()||state.business.owner};next.capacity=Number(f.get('capacity'));next.useHistory=f.has('useHistory');next.fallback=next.products.map((_,i)=>Number(f.get(`fallback-${i}`)));next.ingredients.forEach((g,i)=>{g.stock=Number(f.get(`stock-${i}`));g.pack=Number(f.get(`pack-${i}`));g.cost=Math.round(Number(f.get(`cost-${i}`))*100);});next.products.forEach((p,i)=>{p.name=String(f.get(`name-${i}`)||'').trim()||p.name;p.unit=String(f.get(`unit-${i}`)||'').trim()||'unit';p.price=Math.round(Number(f.get(`price-${i}`))*100);p.batch=Number(f.get(`batch-${i}`));p.minutes=Number(f.get(`minutes-${i}`));p.recipe=next.ingredients.map((_,j)=>Number(f.get(`recipe-${i}-${j}`)));});state=next;state.draft=null;invalidate();settings=false;save();render();toast('Business settings saved. Plan recalculated.');}}
function trapDialog(e){if(e.key==='Escape'&&settings){settings=false;render();return;}if(e.key!=='Tab'||!settings)return;const els=[...document.querySelector('.settings').querySelectorAll('button,input,summary')].filter(el=>el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('settings'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
document.addEventListener('click',bindActions);
document.addEventListener('input',e=>{if(!e.target.dataset.field||e.target.type==='range')return;const id=e.target.id,field=e.target.dataset.field,index=e.target.dataset.index;bindInputs(e);const replacement=id?document.getElementById(id):document.querySelector(`[data-field="${field}"]${index!==undefined?`[data-index="${index}"]`:''}`);replacement?.focus({preventScroll:true});});
document.addEventListener('change',e=>{if(e.target.type==='range')bindInputs(e);});
document.addEventListener('submit',bindForms);
document.addEventListener('keydown',trapDialog);
try{document.modelContext?.registerTool({name:'read_production_plan',title:'Read production plan',description:'Read the current illustrative production plan and constraint warnings without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('No arguments expected.');const p=selectedPlan(state);return {total:p.total,initial:p.initial,preorders:state.orders,purchaseCashCentavos:p.cash,consumedCostCentavos:p.consumed,warnings:p.errors};}});}catch{/* Optional browser capability. */}

